import{_ as t,c as o,o as a,ah as r}from"./chunks/framework.PvdZnrZd.js";const h=JSON.parse('{"title":"Live Commerce","description":"Live Commerce","frontmatter":{"title":"Live Commerce","description":"Live Commerce","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/marketplace-product-add-ons/live-commerce.md","filePath":"zenith/featured-app/marketplace-product-add-ons/live-commerce.md"}'),i={name:"zenith/featured-app/marketplace-product-add-ons/live-commerce.md"};function l(s,e,n,p,c,d){return a(),o("div",null,[...e[0]||(e[0]=[r(`<p><strong><a href="https://apps.shopify.com/webkul-live-commerce" target="_blank" rel="noreferrer">Live</a></strong> <a href="https://apps.shopify.com/webkul-live-commerce" target="_blank" rel="noreferrer"><strong>Commerce</strong></a> turns shopping into an engaging, real-time experience, allowing sellers and customers to interact instantly within a Live Commerce multi-vendor marketplace.</p><p>Instead of relying only on static images and descriptions, brands can showcase products through live video streams and shoppable recordings.</p><p>With our <a href="https://webkul.com/blog/live-commerce/" target="_blank" rel="noreferrer"><strong>Live</strong></a> <strong><a href="https://webkul.com/blog/live-commerce/" target="_blank" rel="noreferrer">Commerce App for Shopify</a></strong>, you can interact with customers in real time, demonstrate products effectively, and drive higher conversions—all in one seamless solution.</p><p>&quot;<strong>The Multivendor Marketplace introduces Live Commerce as a featured app, allowing sellers to use it directly for live selling and shoppable video experiences.</strong>&quot;</p><p><strong>NOTE:- This featured app is only available for the Multivendor Marketplace&#39;s new theme &quot;Zenith&quot;.</strong></p><h2 id="features-in-live-commerce-multivendor-marketplace" tabindex="-1">Features in Live Commerce Multivendor marketplace <a class="header-anchor" href="#features-in-live-commerce-multivendor-marketplace" aria-label="Permalink to &quot;Features in Live Commerce Multivendor marketplace&quot;">​</a></h2><p>Sellers will be able to take advantage of the features listed below:</p><p><strong>Live Streaming Integration</strong>: Go live from a desktop and display products in real-time.</p><p><strong>Shoppable Video</strong>: Viewers can click on products featured in the video and buy them without leaving the video.</p><p><strong>Real-Time Product Sync</strong>: Automatically updates inventory as purchases happen during the stream.</p><p><strong>Analytics Dashboard</strong>: Track live streams, Products, Videos and your digital storage.</p><h2 id="how-to-activate-this-feature-app" tabindex="-1">How to activate this feature app? <a class="header-anchor" href="#how-to-activate-this-feature-app" aria-label="Permalink to &quot;How to activate this feature app?&quot;">​</a></h2><p>To get this feature, you need to install the Live Commerce App on your Shopify store.</p><p>Once done, visit the Feature App section in the Multivenodre Marketplace and activate this featured app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livecommerseactivate-1200x544.webp" alt="live commerce activate"></p><h2 id="configuration-in-live-commerce-multivendor-marketplace" tabindex="-1">Configuration in Live Commerce Multivendor marketplace <a class="header-anchor" href="#configuration-in-live-commerce-multivendor-marketplace" aria-label="Permalink to &quot;Configuration in Live Commerce Multivendor marketplace&quot;">​</a></h2><p><strong>Admin Panel</strong></p><p>After you activate the featured app, the system creates a new <strong>“Live Commerce Configuration”</strong> section in the configuration menu.</p><p>The admin must enable it to make it available for sellers to use.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/adminenablelivecommerce-1200x535.webp" alt="admin side enable"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/adminenablelivecommerceconfirm-1200x535.webp" alt="admin side enable confirm "></p><p>You can grant permissions to sellers from the admin portal, allowing them to <strong>either create shoppable videos, do live streams, or use both features</strong>, based on the access you provide.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/permissiontoseller-1200x535.webp" alt="seller permission Live Commerce Multivendor marketplace"></p><p><strong>Note: Please note that any changes made to the Live Commerce configuration will apply only to newly onboarded sellers. Existing sellers who are already using</strong></p><p><strong>Live Commerce will not be affected. If you want to update permissions for existing sellers, you can do so directly from the Staff section within the Webkul Live Commerce Shopify app.</strong></p><p><strong>Seller Panel</strong></p><p>Once the admin enables this feature, sellers must activate it from their own seller panel as well.<br> They can do this by going to the <strong>Configuration</strong> &gt;&gt; Live commerce configuration.</p><p>After enabling it there, they will be able to use the Live Commerce app features as permitted (shoppable videos, live streaming, or both).</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/enablelivecommerseseller-1200x544.webp" alt="enable seller side  Live Commerce Multivendor marketplace"></p><p>Once the seller enables Live Commerce from the seller panel, the system displays a dedicated button in the header bar, providing direct access to the Live Commerce dashboard.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livecommersebutton-1200x544.webp" alt="live commerce button Live Commerce Multivendor marketplace"></p><p>Clicking this button will redirect the seller to the Live Commerce Dashboard, where they can manage live streams and shoppable videos.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livecommersedashboard2-1200x545.webp" alt="live commerce dashboard  Live Commerce Multivendor marketplace"></p><p>Now, the seller can start adding products to the Live Commerce dashboard.</p><h2 id="add-product-in-live-commerce-multivendor-marketplace" tabindex="-1">Add product in Live Commerce Multivendor marketplace <a class="header-anchor" href="#add-product-in-live-commerce-multivendor-marketplace" aria-label="Permalink to &quot;Add product in Live Commerce Multivendor marketplace&quot;">​</a></h2><p>Saller has to export the product from the product listing section to the live commerce dashboard.</p><p><strong>Saller Panel &gt;&gt; Product Menu &gt;&gt; Product listing.</strong></p><p>Select the product you want to export &gt;&gt; click on the <strong>&quot;Select bulk action&quot;</strong> button &gt;&gt; then click on the <strong>&quot;Export to live commerce&quot;</strong> option and click on confirm.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/exporttolivechat2-1200x545.webp" alt="export product"></p><p>The product will be listed in the product section of the live commerce product dashboard.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livecommerceproductdash-1200x545.webp" alt="product dashboard Live Commerce Multivendor marketplace"></p><p><strong>NOTE:- Only active products can be exported to the live commerce product dashboard.</strong></p><h2 id="shoppable-videos" tabindex="-1">Shoppable Videos <a class="header-anchor" href="#shoppable-videos" aria-label="Permalink to &quot;Shoppable Videos&quot;">​</a></h2><p>Pre-recorded, interactive videos that allow viewers to instantly purchase the featured products by clicking the <strong>Add to Cart</strong> button, creating a smooth and engaging shopping experience.</p><h2 id="how-to-add-shoppable-videos" tabindex="-1">How to add shoppable videos? <a class="header-anchor" href="#how-to-add-shoppable-videos" aria-label="Permalink to &quot;How to add shoppable videos?&quot;">​</a></h2><p>Go to the Live Commerce dashboard &gt;&gt; then navigate to the <strong>&quot;Shoppable videos&quot;</strong> option &gt;&gt; click on the <strong>&quot;Add Video&quot;</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/shoppableaddvideos-1200x545.webp" alt="add video shoppable Live Commerce Multivendor marketplace"></p><p>After clicking on the Add Video button, you have to fill in the following details:</p><ul><li><strong>Title</strong> of the video.</li><li>About your video.</li><li><strong>Thumbnail</strong> for the video.</li><li><strong>Upload the video file</strong>. (Only mp4 video file is allowed)</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/addvideodetailsshoppablevideo-1200x675.webp" alt="video details Live Commerce Multivendor marketplace"></p><p>After successfully uploading the video, you need to tag the products you want to promote with that video.</p><p>These products will appear during playback, allowing viewers to add them directly to the cart without leaving the video.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/producttopromote-1200x545.webp" alt="product to promote Live Commerce Multivendor marketplace"></p><p>Assign timestamps to the tagged products so the system displays them exactly when they are showcased in the video.</p><p>This allows viewers to instantly add the product to their cart at the right moment during playback.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/selecttimeduration-1200x545.webp" alt="select time duration Live Commerce Multivendor marketplace"></p><p>Then,</p><ul><li>Click <strong>&quot;Save&quot;</strong> if you want to save the video as a draft on your dashboard before publishing it to your store.</li><li>Click <strong>&quot;Save &amp; Publish&quot;</strong> to save your video to the dashboard and publish it to the store simultaneously.</li></ul><h2 id="customer-view-of-shoppable-video" tabindex="-1"><strong>Customer View of Shoppable Video</strong> <a class="header-anchor" href="#customer-view-of-shoppable-video" aria-label="Permalink to &quot;**Customer View of Shoppable Video**&quot;">​</a></h2><p>Here’s how it shows on the store frontend:</p><ul><li>The customer clicks on the video</li><li>As the product appears on screen, they click <strong>Add to Cart</strong></li><li>Then proceed to <strong>Checkout</strong></li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/customerendsv-1-1200x545.webp" alt="store frontend customer  Live Commerce Multivendor marketplace"></p><p>When a product appears in the video, the system highlights it in the product list so customers can easily see which product is being displayed at that moment.</p><p>You can add it to your cart just by clicking the <strong>&quot;Add to Cart&quot;</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/shoppablevideoview-1200x545.webp" alt="store frontend add to cart Live Commerce Multivendor marketplace"></p><h2 id="mobile-view" tabindex="-1">Mobile View <a class="header-anchor" href="#mobile-view" aria-label="Permalink to &quot;Mobile View&quot;">​</a></h2><p>This shows how the shoppable video page appears on a mobile phone.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/mobileviewsv-501x1024.webp" alt="mobileviewsv"></p><p>When the product appears in the video, the system highlights it in the product list, making it easy for customers to identify it in real time. Click the <strong>“Add”</strong> button to add it to your cart.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/mobileviewsview-503x1024.webp" alt="mobileviewsview"></p><p>You can view the description of the video from here.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/mobileviewsvdescription-504x1024.webp" alt="mobileviewsvdescription"></p><h2 id="live-streams" tabindex="-1">Live Streams <a class="header-anchor" href="#live-streams" aria-label="Permalink to &quot;Live Streams&quot;">​</a></h2><p>Live streams are real-time video sessions where merchants showcase products, interact with viewers through live chat, and enable instant purchases directly during the broadcast.</p><p>With our Live Commerce featured app for Shopify, you can host live selling events directly on your store, creating a seamless, engaging, and high-conversion shopping experience.</p><h2 id="how-to-create-a-live-stream" tabindex="-1"><strong>How to Create a Live Stream?</strong> <a class="header-anchor" href="#how-to-create-a-live-stream" aria-label="Permalink to &quot;**How to Create a Live Stream?**&quot;">​</a></h2><p>Go to the Live Commerce dashboard &gt;&gt; then navigate to the <strong>&quot;Live Stream&quot;</strong> option,&gt;&gt; click on the <strong>&quot;Create Live Stream&quot;</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livestreamaddvideo-1200x545.webp" alt="Add video live stream Live Commerce Multivendor marketplace"></p><p>Fill in the following details to set up your live stream:</p><ul><li><strong>Title</strong> of the live stream</li><li><strong>Description</strong> to inform viewers what the stream is about</li><li><strong>Thumbnail</strong> image to represent the stream on your store</li><li><strong>Live Stream Duration –</strong> Set the start and end date and time for your stream. The end date duration may vary based on your selected plan.</li><li><strong>Add Products</strong> that will be showcased and sold during the stream</li><li><strong>Enable Live Chat</strong> (optional) to allow real-time interaction with your viewers</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livestreamaddvideodetails-1200x675.webp" alt="Add video details live stream"></p><p>You can also edit your live stream details after scheduling it. Just click on the three dots and then edit.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/livestreamedit-1-1200x545.webp" alt="live stream edit Live Commerce Multivendor marketplace"></p><p>Click Save to schedule the stream or go live at the configured time.</p><p>Once everything is set, the seller can start the live session by clicking “Start Broadcasting.”</p><p>This button also allows you to go live manually before the scheduled time, giving you full control to start streaming whenever you’re ready.</p><p>As soon as broadcasting begins, the stream goes live on your store, enabling customers to join, interact, and shop in real time.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/startbroadcasting-1200x545.webp" alt="Live Commerce Multivendor marketplace start broadcasting"></p><h2 id="track-your-live-streams" tabindex="-1"><strong>Track Your Live Streams</strong> <a class="header-anchor" href="#track-your-live-streams" aria-label="Permalink to &quot;**Track Your Live Streams**&quot;">​</a></h2><p>From the <strong>Live Stream</strong> section, sellers can easily track:</p><ul><li><strong>Current Live Streams</strong> – Sessions that are live right now.</li><li><strong>Upcoming Live Streams</strong> – Scheduled for a future time.</li><li><strong>Recorded Streams</strong> – Previously streamed videos that are published.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/managelivestream-1200x545.webp" alt="Live Commerce Multivendor marketplace manage live stream"></p><h2 id="how-to-add-the-live-shopping-list-extension" tabindex="-1">How to <strong>Add the Live Shopping list extension</strong> <a class="header-anchor" href="#how-to-add-the-live-shopping-list-extension" aria-label="Permalink to &quot;How to **Add the Live Shopping list extension**&quot;">​</a></h2><p>Click on the “Customise” button in the theme section you will be redirected to your theme customisation area.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/05/live-commerce-demo-themes-1200x854.webp" alt="theme "></p><ul><li>Click on the dropdown in the middle &gt;&gt; select “Pages” &gt;&gt; Default Page.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/05/live-commerce-default-pages-1200x854.webp" alt="default-pages"></p><ul><li>Now, on the left-hand side, under template, click on “add block” Select “Apps” &gt;&gt; add “Live Commerce” block.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/05/live-commerece-blocks-1200x854.webp" alt="live-commerece-blocks
"></p><p>Note:- After adding the above extension, you can add a main menu on your storefront and assign a ‘Live Commerce’ page with the same menu.</p><p>Your customers will see your real-time shopping information on the same page.</p>`,101)])])}const u=t(i,[["render",l]]);export{h as __pageData,u as default};
